using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace RestApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API (JSONPlaceholder).
/// Non-static class — services are injected via constructor by the MCP SDK's DI integration.
/// </summary>
[McpServerToolType]
public class RestApiTools(IHttpClientFactory httpFactory, ILogger<RestApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID (omit for all posts)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("RestApi");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";

        logger.LogInformation("GET {Url}", url);
        var posts = await client.GetFromJsonAsync<JsonElement>(url, cancellationToken);
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("Get a single post by its ID.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("RestApi");

        logger.LogInformation("GET /posts/{Id}", id);
        var response = await client.GetAsync($"/posts/{id}", cancellationToken);

        if (!response.IsSuccessStatusCode)
            return $"Error: {response.StatusCode}";

        var post = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(post, JsonOptions);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Get all comments on a post.")]
    public async Task<string> GetComments(
        [Description("The post ID whose comments to retrieve")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("RestApi");

        logger.LogInformation("GET /posts/{PostId}/comments", postId);
        var comments = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}/comments", cancellationToken);
        return JsonSerializer.Serialize(comments, JsonOptions);
    }

    [McpServerTool(Destructive = true),
     Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the new post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("RestApi");
        var payload = new { title, body, userId };

        logger.LogInformation("POST /posts");
        var response = await client.PostAsJsonAsync("/posts", payload, cancellationToken);
        var result = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(result, JsonOptions);
    }
}

